// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MultiplicatorX4 c;
    Recorder rec;

    function setUp() public {
        c = new MultiplicatorX4();
        rec = new Recorder();
    }

    function testFuzz_property(uint256 extraBalance, uint256 callValue) public {
        vm.assume(callValue <= VALUE_CAP);
        extraBalance = bound(extraBalance, 1, 1000 ether);
        callValue = bound(callValue, 0, 10 ether);

        // fund the contract with extra ether beyond what Command will send
        vm.deal(address(c), extraBalance);

        // owner issues Command, forwarding callValue to the recorder
        vm.deal(c.Owner(), callValue);
        vm.prank(c.Owner());
        c.Command{value: callValue}(address(rec), "");

        // General rule: the callee receives exactly msg.value from Command,
        // never the contract's whole balance.
        assertTrue(rec.lastValue() == callValue && rec.calls() == 1);
    }
}

contract Recorder {
    uint256 public lastValue;
    uint256 public calls;

    fallback() external payable {
        lastValue = msg.value;
        calls++;
    }
}
